    visiting = set()

    def visit(p):
        if p in visiting:
410→            errors.append(f"CONFIG_GRAPH_CYCLE:{p}")
            return
        if p in seen:
            return
        visiting.add(p)
        seen.add(p)
        node = by_path.get(p)
        if node:
            for edge in node.get("extendsResolved") or []:
                if edge in by_path:
420→                    visit(edge)
        visiting.discard(p)

    visit(entry)
    for path in by_path:
